"""PayPal sandbox through PayPal's official Python Server SDK (generated by APIMatic).

The SDK accepts paypal_request_id on each call; the ledger fixes one per refund and it is
also sent as the refund's custom_id, so the refund can be found again on the order.
Only the sandbox environment is ever configured here.
"""

import os
import uuid
from pathlib import Path

import requests
from paypalserversdk.configuration import Environment
from paypalserversdk.exceptions.api_exception import ApiException
from paypalserversdk.exceptions.error_exception import ErrorException
from paypalserversdk.http.auth.o_auth_2 import ClientCredentialsAuthCredentials
from paypalserversdk.models.amount_with_breakdown import AmountWithBreakdown
from paypalserversdk.models.card_request import CardRequest
from paypalserversdk.models.checkout_payment_intent import CheckoutPaymentIntent
from paypalserversdk.models.money import Money
from paypalserversdk.models.order_request import OrderRequest
from paypalserversdk.models.payment_source import PaymentSource
from paypalserversdk.models.purchase_unit_request import PurchaseUnitRequest
from paypalserversdk.models.refund_request import RefundRequest
from paypalserversdk.paypal_serversdk_client import PaypalServersdkClient

from .gateway import RefundOutcome, SeenRefund
from .money import to_cents, to_str

ENV_FILE = Path.home() / ".config" / "paypal-remainder" / ".env"

# Published sandbox test card (developer.paypal.com/sandbox-testing/card-testing). Used only
# to create the demo season's registration payments; real payers would use PayPal checkout.
TEST_CARD = {"name": "Demo Family", "number": "4012888888881881", "expiry": "2030-12", "security_code": "123"}

NOTE_LIMIT = 255  # note_to_payer maximum length
TOKEN_URL = "https://api-m.sandbox.paypal.com/v1/oauth2/token"


def load_env_file(path=ENV_FILE):
    values = {}
    if path.exists():
        for line in path.read_text().splitlines():
            line = line.strip()
            if line and not line.startswith("#") and "=" in line:
                key, value = line.split("=", 1)
                values[key.strip()] = value.strip().strip('"').strip("'")
    return values


def _issue(exc):
    details = getattr(exc, "details", None) or []
    for d in details:
        if getattr(d, "issue", None):
            return d.issue
    return getattr(exc, "name", None) or getattr(exc, "reason", "") or type(exc).__name__


class PayPalGateway:
    def __init__(self, client_id, client_secret):
        self._credentials = (client_id, client_secret)
        self.client = PaypalServersdkClient(
            client_credentials_auth_credentials=ClientCredentialsAuthCredentials(
                o_auth_client_id=client_id, o_auth_client_secret=client_secret
            ),
            environment=Environment.SANDBOX,
            timeout=60,
            max_retries=0,  # retries are the runner's job, always with the same request ID
        )

    @classmethod
    def from_env(cls):
        file_values = load_env_file()
        get = lambda key: os.environ.get(key) or file_values.get(key)  # noqa: E731
        client_id, secret = get("PAYPAL_CLIENT_ID"), get("PAYPAL_CLIENT_SECRET")
        if not client_id or not secret:
            raise RuntimeError(f"PAYPAL_CLIENT_ID and PAYPAL_CLIENT_SECRET must be set (env or {ENV_FILE})")
        return cls(client_id, secret)

    def sign_in_problem(self):
        """PayPal's reason for refusing these credentials, or None if it accepts them.

        The SDK reports any failed token request as an expired token, whatever PayPal said.
        """
        try:
            r = requests.post(TOKEN_URL, auth=self._credentials, data={"grant_type": "client_credentials"}, timeout=30)
        except requests.RequestException as exc:
            return f"PayPal could not be reached ({type(exc).__name__})"
        if r.ok:
            return None
        try:
            reason = r.json().get("error_description") or r.json().get("error") or ""
        except ValueError:
            reason = ""
        return f"PayPal answered HTTP {r.status_code}{': ' + reason if reason else ''}"

    def refund(self, capture_id, cents, request_id, note, custom_id):
        options = {
            "capture_id": capture_id,
            "prefer": "return=representation",
            "body": RefundRequest(
                amount=Money(currency_code="USD", value=to_str(cents)),
                note_to_payer=note[:NOTE_LIMIT],
                custom_id=custom_id,
            ),
        }
        if request_id:
            options["paypal_request_id"] = request_id
        try:
            response = self.client.payments.refund_captured_payment(options)
        except ErrorException as exc:
            return RefundOutcome(exc.response_code, error=_issue(exc))
        except ApiException as exc:
            return RefundOutcome(exc.response_code, error=exc.reason)
        except requests.RequestException as exc:
            return RefundOutcome(None, error=type(exc).__name__)
        return RefundOutcome(response.status_code, response.body.id, response.body.status)

    def refunds_on(self, order_id):
        response = self.client.orders.get_order({"id": order_id})
        seen = []
        # SDK models leave optional fields unset rather than None, hence getattr.
        for unit in getattr(response.body, "purchase_units", None) or []:
            payments = getattr(unit, "payments", None)
            for r in getattr(payments, "refunds", None) or []:
                seen.append(
                    SeenRefund(r.id, to_cents(r.amount.value), r.status, getattr(r, "custom_id", None), getattr(r, "create_time", None))
                )
        return seen

    # demo season setup

    def pay_with_test_card(self, label, cents):
        body = OrderRequest(
            intent=CheckoutPaymentIntent.CAPTURE,
            purchase_units=[
                PurchaseUnitRequest(reference_id=label, amount=AmountWithBreakdown(currency_code="USD", value=to_str(cents)))
            ],
            payment_source=PaymentSource(card=CardRequest(**TEST_CARD)),
        )
        response = self.client.orders.create_order(
            {"body": body, "paypal_request_id": str(uuid.uuid4()), "prefer": "return=representation"}
        )
        order = response.body
        if order.status != "COMPLETED":
            raise RuntimeError(f"order {order.id} for {label} is {order.status}, expected COMPLETED")
        capture = order.purchase_units[0].payments.captures[0]
        return order.id, capture.id, capture.create_time

    def refund_in_full(self, capture_id, cents):
        key = str(uuid.uuid4())
        outcome = self.refund(capture_id, cents, key, "Refunded in full.", key)
        if outcome.http_status != 201:
            raise RuntimeError(f"full refund of {capture_id} failed: {outcome}")
        return outcome.refund_id
